import{_ as o,a0 as p,w as d,s as r,ao as n,I as t,x as e,a1 as i,A as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"命令別名：定義自己的命令 | LCTT x X-CMD","titleTemplate":false,"description":"命令別名：定義自己的命令 | LCTT (201812) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"命令別名：定義自己的命令 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"命令別名：定義自己的命令 | LCTT (201812) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201812/20181212 Aliases- DIY Shell Commands","title":"命令別名：定義自己的命令","tag":"201812","desc":""},"relativePath":"201812/20181212 Aliases- DIY Shell Commands.md","filePath":"[post].md"}'),c={name:"201812/20181212 Aliases- DIY Shell Commands.md"};function u(h,s,g,k,b,f){const a=p("Link");return d(),r("div",null,[s[25]||(s[25]=n('<h1 id="命令別名-定義自己的命令" tabindex="-1">命令別名：定義自己的命令 <a class="header-anchor" href="#命令別名-定義自己的命令" aria-label="Permalink to “命令別名：定義自己的命令”">​</a></h1><blockquote><p>學習如何創建別名：你可以將太長或難以記憶的命令打包成你自己構建的命令。</p></blockquote><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/jodi-mucha-540841-unsplash.jpg?itok=n1d1VDUV" alt=""></p><p><ruby>命令別名<rt>Alias</rt></ruby>在 Linux shell 中指的是將一些太長或者太難記的多個命令組合起來，成為一個由用户自己構建的命令。</p><p>可以通過 <code>alias</code> 命令來創建命令別名。在 <code>alias</code> 後面跟上想要創建的別名名稱、一個等號（<code>=</code>），以及希望使用這個別名來執行的命令，這樣一個命令別名就創建好了。舉個例子，<code>ls</code> 命令在默認情況下是不會對輸出的內容進行着色的，這樣就不能讓用户一眼分辨出目錄、文件和連接了。對此，可以創建這樣一個命令別名，在輸出目錄內容的時候為輸出內容着色：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias lc=&#39;ls --color=auto&#39;</span></span></code></pre></div><p>其中 <code>lc</code> 是自定義的命令別名，代表 “list with color” 的意思。在創建命令別名的時候，需要先確認使用的別名是不是已經有對應的命令了，如果有的話，原本的命令就會被覆蓋掉了。注意，定義命令別名的時候，<code>=</code> 兩端是沒有空格的。當運行 <code>lc</code> 的時候，就相當於執行了 <code>ls --color</code> 命令。</p><p>此後，執行 <code>lc</code> 列出目錄內容的時候，就會輸出帶有着色的內容了。</p><p>你可能會發現你在執行 <code>ls</code> 的時候，本來就是輸出帶有着色的內容。那是因為大部分 Linux 發行版都已經將 <code>ls</code> 設定為帶有着色的命令別名了。</p><h3 id="可以直接使用的命令別名" tabindex="-1">可以直接使用的命令別名 <a class="header-anchor" href="#可以直接使用的命令別名" aria-label="Permalink to “可以直接使用的命令別名”">​</a></h3><p>實際上，執行不帶任何內容的 <code>alias</code> 命令就可以看到當前已經設定的所有命令別名。對於不同的發行版，包含的命令別名不盡相同，但普遍都會有以下這些命令別名：</p><ul><li><code>alias ls=&#39;ls --color=auto&#39;</code>：這個命令別名在前面已經提到過了。<code>--color=auto</code> 參數會讓 <code>ls</code> 命令在通過標準輸出在終端中顯示內容時進行着色，而其它情況（例如通過管道輸出到文件）下則不進行着色。<code>--color</code> 這個參數還可以設置為 <code>always</code> 或<code>never</code>。</li><li><code>alias cp=&#39;cp -i&#39;</code>：<code>-i</code> 參數代表“<ruby>交互<rt>interactive</rt></ruby>”。在使用 <code>cp</code> 命令複製文件的時候，可能會無意中覆蓋現有的文件，在使用了 <code>-i</code> 參數之後，<code>cp</code> 命令會在一些關鍵操作前向用户發出詢問。</li><li><code>alias free=&#39;free -m&#39;</code>：在 <code>free</code> 命令後面加上 <code>-m</code> 參數，就可以將輸出的內存信息以 MiB 這個更方面閲讀和計算的單位輸出，而不是默認的 Byte 單位。</li></ul><p>你使用的發行版自帶的命令別名可能多多少少和上面有些差別。但你都可以在命令前面加上 <code>\\</code> 修飾符來使用命令的最基本形式（而不是別名）。例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>\\free</span></span></code></pre></div><p>就是直接執行 <code>free</code>，而不是 <code>free -m</code>。還有：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>\\ls</span></span></code></pre></div><p>執行的就是不帶有<code>--color=auto</code> 參數的 <code>ls</code>。</p>',17)),t("p",null,[s[1]||(s[1]=e("如果想要持久地保存命令別名，可以在 ",-1)),s[2]||(s[2]=t("code",null,".bashrc",-1)),s[3]||(s[3]=e(" 文件中進行修改，而它",-1)),i(a,{href:"https://linux.cn/article-10370-1.html"},{default:l(()=>[...s[0]||(s[0]=[e("來源於我們的 /etc/skel 目錄",-1)])]),_:1}),s[4]||(s[4]=e("。",-1))]),s[26]||(s[26]=n(`<h3 id="使用命令別名糾正錯誤" tabindex="-1">使用命令別名糾正錯誤 <a class="header-anchor" href="#使用命令別名糾正錯誤" aria-label="Permalink to “使用命令別名糾正錯誤”">​</a></h3><p>各種發行版的設計者都會盡量設置用户可能需要用到的命令別名。但是不同的用户的習慣各不相同，一些用户可能剛從其它操作系統遷移到 Linux，而不同操作系統的基本命令又因 shell 而異。因此，對於剛從 Windows/MS-DOS 系統遷移到 Linux 系統的用户，不妨使用</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias dir=&#39;ls&#39;</span></span></code></pre></div><p>這個命令別名來列出目錄內容。</p><p>類似地，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias copy=&#39;cp&#39;</span></span>
<span class="line"><span>alias move=&#39;mv&#39;</span></span></code></pre></div><p>也可以在尚未完全熟悉 Linux 的時候用得順手。</p><p>還有一種情況，就是在經常出現輸入錯誤的場合中做出容錯，例如，對於我來説， Administration 這個單詞就很難快速正確地輸入，因此很多用户都會設置類似這樣的別名：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias sl=&#39;ls&#39;</span></span></code></pre></div><p>以及</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias gerp=&#39;echo &quot;You did it *again*!&quot;; grep&#39;</span></span></code></pre></div><p><code>grep</code> 命令最基本的用途就是在文件中查找字符串，在熟悉這個命令之後，它一定是最常用的命令之一，因此輸入錯誤導致不得不重輸命令就很令人抓狂。</p><p>在上面 <code>gerp</code> 的例子中，包含的不只是一條命令，而是兩條。第一條命令 <code>echo &quot;You did it *again*!&quot;</code> 輸出了一條提醒用户拼寫錯誤的消息，然後使用分號（<code>；</code>）把兩條命令隔開，再往後才是 <code>grep</code> 這一條正確的命令。</p><p>在我的系統上使用 <code>gerp</code> 來搜索 <code>/etc/skel/.bashrc</code> 中包含“alias”這個單詞的行，就會輸出以下內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gerp -R alias /etc/skel/.bashrc</span></span>
<span class="line"><span>You did it *again*! </span></span>
<span class="line"><span>       alias ls=&#39;ls --color=auto&#39; </span></span>
<span class="line"><span>       alias grep=&#39;grep --colour=auto&#39; </span></span>
<span class="line"><span>       alias egrep=&#39;egrep --colour=auto&#39; </span></span>
<span class="line"><span>       alias fgrep=&#39;fgrep --colour=auto&#39; </span></span>
<span class="line"><span>alias cp=&quot;cp -i&quot;</span></span>
<span class="line"><span>alias df=&#39;df -h&#39;</span></span>
<span class="line"><span>alias free=&#39;free -m&#39;</span></span>
<span class="line"><span>alias np=&#39;nano -w PKGBUILD&#39; </span></span>
<span class="line"><span>alias more=less </span></span>
<span class="line"><span>shopt -s expand_aliases</span></span></code></pre></div><p>在命令別名中以固定的順序執行多個命令，甚至更進一步，把多個命令串連起來，讓後面的命令可以使用到前面的命令的執行結果。這樣的做法已經非常接近 bash 腳本了。這篇文章已經接近尾聲，我們將在下一篇文章中詳細介紹。</p><p>如果想要刪除在終端中臨時設置的別名，可以使用 <code>unalias</code> 命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>unalias gerp</span></span></code></pre></div>`,18)),t("p",null,[s[6]||(s[6]=e("如果想要持久保存命令別名，可以將命令別名放在用户主目錄的 ",-1)),s[7]||(s[7]=t("code",null,".bashrc",-1)),s[8]||(s[8]=e(" 文件中，具體的方法在",-1)),i(a,{href:"https://linux.cn/article-10374-1.html"},{default:l(()=>[...s[5]||(s[5]=[e("上一篇文章",-1)])]),_:1}),s[9]||(s[9]=e("中已經介紹過。",-1))]),s[27]||(s[27]=t("hr",null,null,-1)),t("p",null,[s[11]||(s[11]=e("via: ",-1)),i(a,{href:"https://www.linux.com/blog/learn/2018/12/aliases-diy-shell-commands"},{default:l(()=>[...s[10]||(s[10]=[e("https://www.linux.com/blog/learn/2018/12/aliases-diy-shell-commands",-1)])]),_:1})]),t("p",null,[s[16]||(s[16]=e("作者：",-1)),i(a,{href:"https://www.linux.com/users/bro66"},{default:l(()=>[...s[12]||(s[12]=[e("Paul Brown",-1)])]),_:1}),s[17]||(s[17]=e(" 選題：",-1)),i(a,{href:"https://github.com/lujun9972"},{default:l(()=>[...s[13]||(s[13]=[e("lujun9972",-1)])]),_:1}),s[18]||(s[18]=e(" 譯者：",-1)),i(a,{href:"https://github.com/HankChow"},{default:l(()=>[...s[14]||(s[14]=[e("HankChow",-1)])]),_:1}),s[19]||(s[19]=e(" 校對：",-1)),i(a,{href:"https://github.com/wxy"},{default:l(()=>[...s[15]||(s[15]=[e("wxy",-1)])]),_:1})]),t("p",null,[s[22]||(s[22]=e("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...s[20]||(s[20]=[e("LCTT",-1)])]),_:1}),s[23]||(s[23]=e(" 原創編譯，",-1)),i(a,{href:"https://linux.cn/"},{default:l(()=>[...s[21]||(s[21]=[e("Linux中國",-1)])]),_:1}),s[24]||(s[24]=e(" 榮譽推出",-1))])])}co